import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9ddd1');scene.fog=new THREE.Fog('#a9ddd1',30,56);
const camera=new THREE.OrthographicCamera(-12,12,9,-9,.1,100);camera.position.set(0,19,21);camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight('#fff8d8','#669576',2.1));const sun=new THREE.DirectionalLight('#fff2cd',2.5);sun.position.set(-8,16,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-18;sun.shadow.camera.right=18;sun.shadow.camera.top=18;sun.shadow.camera.bottom=-18;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={grass:mat('#77ba79'),edge:mat('#5a9c6f'),path:mat('#e9cc8e'),pathDark:mat('#d6b77c'),water:mat('#59b9ba',.35),wood:mat('#a76d49'),darkWood:mat('#80523b'),cream:mat('#fff1c8'),red:mat('#e88966'),leaf:mat('#43916a'),leaf2:mat('#64ad72'),flower:mat('#fff1d2')};
const ground=new THREE.Mesh(new THREE.CylinderGeometry(11.9,12.2,.65,64),mat('#6aab71'));ground.position.y=-.42;ground.receiveShadow=true;scene.add(ground);
const lawn=new THREE.Mesh(new THREE.CircleGeometry(11.8,64),mats.grass);lawn.rotation.x=-Math.PI/2;lawn.position.y=-.08;lawn.receiveShadow=true;scene.add(lawn);
function flatShape(points,material,y=.01){const s=new THREE.Shape();s.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)s.lineTo(points[i][0],points[i][1]);s.closePath();const m=new THREE.Mesh(new THREE.ShapeGeometry(s),material);m.rotation.x=-Math.PI/2;m.position.y=y;m.receiveShadow=true;scene.add(m);return m;}
// Soft winding path through the meadow
flatShape([[-8,7],[-6.4,6.6],[-4.8,5.3],[-4.3,3.8],[-3.4,2.4],[-1.4,1.8],[1,1.9],[3.3,2.6],[5.3,2.3],[7,1.6],[8.2,.4],[8.4,-1],[7.3,-2],[5.4,-2.5],[4.4,-1.7],[5.8,-.4],[7.2,.3],[7.4,1.1],[5,1.8],[2.5,1.3],[.2,1.1],[-2,1.3],[-3.5,2],[-4.7,3.6],[-5,5],[-6.7,6.8]],mats.path,.005);
