const pond=new THREE.Mesh(new THREE.CircleGeometry(1,64),mats.water);pond.scale.set(6.45,4.35,1);pond.rotation.x=-Math.PI/2;pond.position.set(-.3,.12,-.3);pond.receiveShadow=true;scene.add(pond);
const waterInner=new THREE.Mesh(new THREE.CircleGeometry(1,64),mat('#6ac9c2',.3));waterInner.scale.set(5.5,3.55,1);waterInner.rotation.x=-Math.PI/2;waterInner.position.set(-.3,.135,-.3);scene.add(waterInner);
const rings=[];for(let i=0;i<5;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(1,.025,6,48),new THREE.MeshBasicMaterial({color:'#c6f5dc',transparent:true,opacity:.38}));ring.rotation.x=Math.PI/2;ring.position.set(-4.2+i*1.7,.16,-1.1+(i%2)*1.25);ring.scale.set(.55,.35,1);scene.add(ring);rings.push(ring)}
// Simple geometry helpers
function box(parent,w,h,d,material,x,y,z){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function sphere(parent,r,material,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;parent.add(o);return o}
function tree(x,z,size=1){const g=new THREE.Group();g.position.set(x,0,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*size,.22*size,.9*size,8),mats.wood);trunk.position.y=.38*size;trunk.castShadow=true;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry((.62-i*.07)*size,1),i===1?mats.leaf2:mats.leaf);crown.position.set((i-1)*.34*size,(.88+i*.35)*size,0);crown.scale.set(1,1.05,.95);crown.castShadow=true;g.add(crown)}scene.add(g);return g}
function bush(x,z){const g=new THREE.Group();g.position.set(x,0,z);for(let i=0;i<4;i++){sphere(g,.32,i%2?mats.leaf2:mats.leaf,(i-1.5)*.24,.25+(i%2)*.08,0,1.1,.85,1)}scene.add(g)}
const trees=[[-9,-6,1.05],[-8,-2,.85],[-9,2,1],[-7,-8,.9],[-3,-9,1.05],[1,-9,.85],[5,-8,1.05],[9,-5,1],[9,4,.9],[6,8,1.05],[2,9,.9],[-3,9,.95],[-9,7,.88],[8,-.3,.72]];trees.forEach(p=>tree(...p));
[[-7,-4],[-7,1],[6,5],[2,7],[9,2],[-5,8],[4,-7]].forEach(p=>bush(...p));
// flower specks along lawn
for(let i=0;i<34;i++){const a=i*2.399,r=6.9+(i%5)*.55,x=Math.cos(a)*r,z=Math.sin(a)*r;const f=new THREE.Mesh(new THREE.SphereGeometry(.055,6,6),i%3?mats.flower:mat('#f3c76e'));f.position.set(x,.04,z);scene.add(f)}
// Market stall: red-and-cream striped awning and a welcoming counter
const stall=new THREE.Group();stall.position.set(6,0,-2.6);scene.add(stall);
box(stall,2.7,.95,.82,mats.wood,0,.62,0);box(stall,2.82,.12,.9,mats.darkWood,0,1.12,0);
for(const x of [-1.12,1.12]){box(stall,.14,2.35,.14,mats.darkWood,x,1.15,-.25);box(stall,.12,2.35,.12,mats.darkWood,x,1.15,.22)}
const roof=new THREE.Mesh(new THREE.BoxGeometry(3.1,.2,1.35),mats.red);roof.position.set(0,2.2,-.08);roof.castShadow=true;stall.add(roof);
for(let i=0;i<7;i++){const stripe=box(stall,.42,.24,1.37,i%2?mats.cream:mat('#f1a071'),-1.29+i*.43,2.15,-.08);stripe.rotation.z=(i-3)*.008}
const sign=box(stall,1.55,.47,.12,mat('#fff1c8'),0,1.56,.49);const signText=document.createElement('canvas');signText.width=512;signText.height=128;const ctx=signText.getContext('2d');ctx.fillStyle='#fff0c9';ctx.fillRect(0,0,512,128);ctx.fillStyle='#477755';ctx.font='bold 54px sans-serif';ctx.textAlign='center';ctx.fillText('FISH MARKET',256,83);const tex=new THREE.CanvasTexture(signText);const signface=new THREE.Mesh(new THREE.PlaneGeometry(1.5,.38),new THREE.MeshBasicMaterial({map:tex,transparent:true}));signface.position.set(0,1.56,.56);stall.add(signface);
// Little market crates and fish display
for(let i=0;i<3;i++){box(stall,.37,.22,.33,i===1?mat('#e9c36f'):mat('#6b9b70'),-.68+i*.67,.29,.12);sphere(stall,.11,i===1?mat('#e78668'):mat('#7eb9c4'),-.69+i*.67,.48,.12,1.8,.7,.5)}

